/**
 * 微前端沙箱探测（按渲染拓扑分派，框架无关）。
 *
 * 拓扑三分：
 * - 同文档（无沙箱 / qiankun / micro-app light DOM / 降级 iframe）：absolute 正确
 * - 真 shadow DOM（web component 沙箱 / micro-app shadowDOM 模式）：absolute 正确，
 *   由组件的 `getRootNode() instanceof ShadowRoot` 检测命中
 * - graft 型（wujie）：iframe 文档树 graft 进 shadowRoot 渲染，absolute 输出视口系
 *   坐标但包含块是 graft body → 错位；fixed 以最近视口为包含块，是唯一正确解
 *
 * 安全性论证：非 graft 拓扑下 absolute 与 fixed 坐标等价（包含块同为最近视口），
 * iframe realm 下默认 fixed 零副作用；跨域 iframe 下 self/top 仅引用比较，
 * 不读属性，无 SecurityError。
 *
 * 已知边界：
 * - fixed 元素祖先有 transform/filter 时包含块被劫持（宿主布局应避免；graft 下
 *   absolute 的 offsetParent 解析本就失效，错法不同而非新增错误）
 * - fixed 面板在祖先滚动时依赖 autoUpdate 重算，重算前一帧有视口驻留（瞬时视觉差异）
 * - 若未来出现「非 iframe 的 graft 型沙箱」，本探测无法覆盖，需追加该沙箱的 marker 信号
 */

/** 组件 JS 是否运行在 iframe realm（wujie / iframe 型沙箱 / 普通 iframe 嵌入） */
export function isInIframeRealm(): boolean {
  return typeof window !== "undefined" && window.self !== window.top;
}

/** 是否处于 wujie graft 沙箱（getRootNode/父链被 wujie patch 伪装，结构探测失效，
 *  依赖官方标记；wujie 在子应用脚本执行前注入，时序可靠） */
export function isInWujie(): boolean {
  return (
    typeof window !== "undefined" &&
    (window as { __POWERED_BY_WUJIE__?: boolean }).__POWERED_BY_WUJIE__ === true
  );
}

import { ref, type ComponentInternalInstance } from "vue";

export interface ConfirmPendingOptions {
  /** 当前组件实例：从 vnode 上取原始 onConfirm 监听器（emit 不回传返回值） */
  instance: ComponentInternalInstance | null;
  /** 无监听器时补发 confirm 事件 */
  emitConfirm: () => void;
  emitCancel: () => void;
  /** 关闭弹层（走受控桥） */
  close: () => void;
}

/**
 * 确认弹层公共 pending 语义：@confirm 处理器返回 Promise 时锁定关闭通道，
 * resolve 后自动关闭，reject 保持打开并退出 loading；同步处理器直接关闭。
 */
export function useConfirmPending(options: ConfirmPendingOptions) {
  const loading = ref(false);

  function handleConfirm() {
    if (loading.value) return;
    const handler = options.instance?.vnode.props?.onConfirm as
      | ((...args: unknown[]) => unknown)
      | undefined;
    const result = handler?.();
    if (!handler) options.emitConfirm();
    if (result instanceof Promise) {
      loading.value = true;
      result
        .then(() => {
          loading.value = false;
          options.close();
        })
        .catch(() => {
          loading.value = false;
        });
    } else {
      options.close();
    }
  }

  function handleCancel() {
    if (loading.value) return;
    options.emitCancel();
    options.close();
  }

  return { loading, handleConfirm, handleCancel };
}

import { computed, ref, type ComputedRef } from "vue";

export interface ControlledBooleanOptions {
  /** 受控值；返回 undefined 表示非受控（内部状态接管） */
  controlled: () => boolean | undefined;
  /** 非受控初始值 */
  defaultValue?: () => boolean;
  /** 状态变更对外同步（一般 emit("update:open", next)） */
  onChange?: (next: boolean) => void;
}

export interface ControlledBoolean {
  isOpen: ComputedRef<boolean>;
  setOpen: (next: boolean) => void;
}

/**
 * 业务组件惯例：Ark Root 恒走受控，非受控语义由内部 ref 实现。
 * `controlled()` 返回 undefined 时用内部值，否则永远跟随外部 prop。
 */
export function useControlledBoolean(options: ControlledBooleanOptions): ControlledBoolean {
  const internal = ref(options.defaultValue?.() ?? false);
  const isOpen = computed(() => options.controlled() ?? internal.value);

  function setOpen(next: boolean) {
    internal.value = next;
    options.onChange?.(next);
  }

  return { isOpen, setOpen };
}
